from collections import Counter


def _components(grid, background):
    h, w = len(grid), len(grid[0])
    seen, objects = set(), []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == background or (r, c) in seen:
                continue
            seen.add((r, c))
            stack = [(r, c)]
            cells = set()
            while stack:
                y, x = stack.pop()
                cells.add((y, x))
                for yy in range(y - 1, y + 2):
                    for xx in range(x - 1, x + 2):
                        if (yy, xx) == (y, x):
                            continue
                        if (0 <= yy < h and 0 <= xx < w and (yy, xx) not in seen
                                and grid[yy][xx] == color):
                            seen.add((yy, xx))
                            stack.append((yy, xx))
            rs = [p[0] for p in cells]
            cs = [p[1] for p in cells]
            objects.append({'color': color, 'cells': cells,
                            'r0': min(rs), 'r1': max(rs),
                            'c0': min(cs), 'c1': max(cs)})
    return objects


def _shape(obj):
    return frozenset((r - obj['r0'], c - obj['c0']) for r, c in obj['cells'])


def _corner_frame(obj):
    cells = obj['cells']
    r0, r1, c0, c1 = obj['r0'], obj['r1'], obj['c0'], obj['c1']
    if r0 == r1 or c0 == c1:
        return False
    for r in (r0, r1):
        for c in (c0, c1):
            corner_l = ({(r, x) for x in range(c0, c1 + 1)} |
                        {(y, c) for y in range(r0, r1 + 1)})
            if cells == corner_l:
                return True
    return False


def _inside(obj, frame):
    return (frame['r0'] <= obj['r0'] and obj['r1'] <= frame['r1'] and
            frame['c0'] <= obj['c0'] and obj['c1'] <= frame['c1'])


def transform(grid):
    out = [row[:] for row in grid]
    background = Counter(v for row in grid for v in row).most_common(1)[0][0]
    objects = _components(grid, background)
    for frame in objects:
        if not _corner_frame(frame):
            continue
        samples = [o for o in objects if o is not frame and _inside(o, frame)]
        for sample in samples:
            candidates = [o for o in objects if o is not frame and o is not sample
                          and not _inside(o, frame) and _shape(o) == _shape(sample)]
            if len(candidates) == 1:
                target = candidates[0]
                for r, c in target['cells']:
                    out[r][c] = frame['color']
                return out
    return out

