from collections import Counter


def components(grid, background):
    h, w = len(grid), len(grid[0])
    seen, result = set(), []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == background or (r, c) in seen:
                continue
            seen.add((r, c))
            stack = [(r, c)]
            cells = set()
            while stack:
                y, x = stack.pop()
                cells.add((y, x))
                for yy, xx in ((y-1, x), (y+1, x), (y, x-1), (y, x+1)):
                    if 0 <= yy < h and 0 <= xx < w and (yy, xx) not in seen and grid[yy][xx] == color:
                        seen.add((yy, xx))
                        stack.append((yy, xx))
            rs = [p[0] for p in cells]
            cs = [p[1] for p in cells]
            result.append({'color': color, 'cells': cells, 'r0': min(rs), 'r1': max(rs), 'c0': min(cs), 'c1': max(cs)})
    return result


def shape(obj):
    return frozenset((r - obj['r0'], c - obj['c0']) for r, c in obj['cells'])


def is_corner_l(obj):
    cells = obj['cells']
    r0, r1, c0, c1 = obj['r0'], obj['r1'], obj['c0'], obj['c1']
    if r0 == r1 or c0 == c1:
        return False
    return any(cells == ({(r, c) for c in range(c0, c1+1)} | {(r, c) for r in range(r0, r1+1)})
               for r in (r0, r1) for c in (c0, c1))


def inside(obj, frame):
    return frame['r0'] <= obj['r0'] and obj['r1'] <= frame['r1'] and frame['c0'] <= obj['c0'] and obj['c1'] <= frame['c1']


def transform(grid):
    out = [row[:] for row in grid]
    background = Counter(v for row in grid for v in row).most_common(1)[0][0]
    objs = components(grid, background)
    for frame in objs:
        if not is_corner_l(frame):
            continue
        samples = [o for o in objs if o is not frame and inside(o, frame)]
        for sample in samples:
            outside = [o for o in objs if o is not frame and o is not sample and not inside(o, frame)]
            exact = [o for o in outside if shape(o) == shape(sample)]
            if len(exact) == 1:
                target = exact[0]
            elif not exact:
                dims = (sample['r1']-sample['r0'], sample['c1']-sample['c0'])
                candidates = [o for o in outside if (o['r1']-o['r0'], o['c1']-o['c0']) == dims]
                if not candidates:
                    continue
                scores = [(len(shape(sample) ^ shape(o)), o) for o in candidates]
                best = min(score for score, _ in scores)
                winners = [o for score, o in scores if score == best]
                if len(winners) != 1:
                    continue
                target = winners[0]
            else:
                continue
            # Paint the sample silhouette over the closest equal-size target box.
            # When the silhouettes differ, only their shared occupied cells match.
            sample_cells = shape(sample)
            target_cells = shape(target)
            shared = sample_cells & target_cells
            for dr, dc in shared:
                out[target['r0'] + dr][target['c0'] + dc] = frame['color']
            return out
    return out

