def _components(grid, background):
    h, w = len(grid), len(grid[0])
    seen, result = set(), []
    for r in range(h):
        for c in range(w):
            if grid[r][c] == background or (r, c) in seen:
                continue
            color = grid[r][c]
            stack = [(r, c)]
            seen.add((r, c))
            cells = set()
            while stack:
                y, x = stack.pop()
                cells.add((y, x))
                for yy, xx in ((y-1, x), (y+1, x), (y, x-1), (y, x+1)):
                    if (0 <= yy < h and 0 <= xx < w and (yy, xx) not in seen
                            and grid[yy][xx] == color):
                        seen.add((yy, xx))
                        stack.append((yy, xx))
            rs = [p[0] for p in cells]
            cs = [p[1] for p in cells]
            result.append({
                'color': color, 'cells': cells,
                'r0': min(rs), 'r1': max(rs), 'c0': min(cs), 'c1': max(cs),
            })
    return result


def _shape(obj):
    return frozenset((r - obj['r0'], c - obj['c0']) for r, c in obj['cells'])


def _corner_frame(obj):
    """True for a one-cell-thick L formed by two perpendicular bbox edges."""
    cells = obj['cells']
    r0, r1, c0, c1 = obj['r0'], obj['r1'], obj['c0'], obj['c1']
    if r0 == r1 or c0 == c1:
        return False
    horizontal = [r for r in (r0, r1)
                  if all((r, c) in cells for c in range(c0, c1 + 1))]
    vertical = [c for c in (c0, c1)
                if all((r, c) in cells for r in range(r0, r1 + 1))]
    for r in horizontal:
        for c in vertical:
            allowed = ({(r, x) for x in range(c0, c1 + 1)} |
                       {(y, c) for y in range(r0, r1 + 1)})
            if cells <= allowed and (r, c) in cells:
                return True
    return False


def transform(grid):
    out = [row[:] for row in grid]
    background = Counter(v for row in grid for v in row).most_common(1)[0][0]
    objects = _components(grid, background)

    for frame in objects:
        if not _corner_frame(frame):
            continue
        inside = [obj for obj in objects if obj is not frame and
                  frame['r0'] <= obj['r0'] and obj['r1'] <= frame['r1'] and
                  frame['c0'] <= obj['c0'] and obj['c1'] <= frame['c1']]
        for sample in inside:
            signature = _shape(sample)
            for target in objects:
                if target is frame or target is sample:
                    continue
                if (frame['r0'] <= target['r0'] and target['r1'] <= frame['r1'] and
                        frame['c0'] <= target['c0'] and target['c1'] <= frame['c1']):
                    continue
                if _shape(target) == signature:
                    for r, c in target['cells']:
                        out[r][c] = frame['color']
                    return out
    return out
